    <script>
        document.querySelectorAll('#preguntas details').forEach((item) => {
            item.addEventListener('toggle', () => {
                if (!item.open) {
                    return;
                }

                document.querySelectorAll('#preguntas details[open]').forEach((openItem) => {
                    if (openItem !== item) {
                        openItem.open = false;
                    }
                });
            });
        });
    </script>
